commits.content:
:host {
  display: block;
  width: 100%;
  position: sticky;
  top: 0;
  z-index: 50;
}

nav {
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

/* Animação sutil para o badge do plano */
span {
  transition: all 0.3s ease;
}

button:focus-visible {
  outline: 2px solid #10b981;
  outline-offset: 2px;
}
